-- Mora de 1.4.02 por préstamo al 30-sep-2025: neto global contra tope por préstamo (piso 0), y la mora cobrada antes del ancla.
-- Respuesta al árbitro sobre el bloque 5 de la 391 de c728ba3a. Solo SELECT.
WITH m AS (SELECT PRSTCDGO, SUM(CASE MVICTPMV WHEN 5 THEN MVICVLOR WHEN 6 THEN -MVICVLOR ELSE 0 END) dev, SUM(CASE MVICTPMV WHEN 9 THEN MVICVLOR ELSE 0 END) c9
           FROM CRD.MVIC WHERE MVICCMPN=2 AND MVICTPMV IN (5,6,9) AND NVL(MVICANUL,0)=0 AND MVICFCCT <= DATE '2025-09-30' GROUP BY PRSTCDGO),
g AS (SELECT PRSTCDGO, SUM(NVL(PGPRMRPG,0)) pg FROM CRD.PGPR WHERE NVL(PGPRANUL,0)=0 AND PGPRFCHA >= DATE '2025-06-01' AND PGPRFCHA < DATE '2025-10-01' GROUP BY PRSTCDGO),
x AS (SELECT NVL(m.PRSTCDGO,g.PRSTCDGO) p, NVL(dev,0) dev, NVL(c9,0) c9, NVL(pg,0) pg FROM m FULL JOIN g ON g.PRSTCDGO=m.PRSTCDGO)
SELECT ROUND(SUM(dev-pg-c9),2) NETO_GLOBAL, ROUND(SUM(GREATEST(0,dev-pg-c9)),2) TOPE_POR_PRESTAMO, ROUND(SUM(LEAST(0,dev-pg-c9)),2) NEGATIVOS,
       ROUND(SUM(CASE WHEN dev-pg-c9<0 THEN c9 ELSE 0 END),2) C9_NEG, ROUND(SUM(CASE WHEN dev-pg-c9<0 THEN pg ELSE 0 END),2) PG_NEG, ROUND(SUM(CASE WHEN dev-pg-c9<0 THEN dev ELSE 0 END),2) DEV_NEG, COUNT(CASE WHEN dev-pg-c9<0 THEN 1 END) N_NEG FROM x;
SELECT ROUND(SUM(PGPRMRPG),2) MORA_COBRADA_ANTES_ANCLA FROM CRD.PGPR WHERE NVL(PGPRANUL,0)=0 AND PGPRFCHA < DATE '2025-06-01' AND NVL(PGPRMRPG,0)>0
  AND PRSTCDGO IN (SELECT PRSTCDGO FROM CRD.MVIC WHERE MVICTPMV IN (5,6) AND MVICCMPN=2);
